package com.commercecore.order;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;@Component public class OrderExpiryScheduler{private final OrderService orders;public OrderExpiryScheduler(OrderService o){orders=o;}@Scheduled(fixedDelayString="${app.checkout.expiry-scan-interval:1m}")public void expire(){orders.expirePendingOrders();}}
